  var current = 5;
  var sum = 0;
  var state: Option[Int] = Some(current);
  while let Some(n) = state {
    sum = sum + n;
    if n > 1 {
      state = Some(n - 1);
    } else {
      state = None;
    }
  }
  return sum;
